/**
 * The free-atom core densities the ESP surface adds back to GFN2's valence
 * density (core-density.ts; generated by scripts/core-densities/ from ORCA
 * X2C atoms, 2026-10-21). Read through the app's own interpolation, each
 * table row must still hold its core's electrons, and the cores must reach
 * the 0.001 au surface level where the free-atom calculations put it.
 */
import { describe, expect, it } from 'vitest';
import { coreDensity, coreReach } from '../src/chem/charge-model/core-density';

const ANGSTROM_PER_BOHR = 0.529177;

/** ∫ 4π r² ρ dr by the trapezoid rule in ln r, from the nucleus out. */
function electrons(element: string): number {
  const steps = 4000;
  const first = Math.log(1e-4);
  const last = Math.log(coreReach(element) + 1);
  let sum = 0;
  for (let k = 0; k <= steps; k++) {
    const r = Math.exp(first + ((last - first) * k) / steps);
    const weight = k === 0 || k === steps ? 0.5 : 1;
    sum += weight * 4 * Math.PI * r ** 3 * coreDensity(element, r);
  }
  return (sum * (last - first)) / steps;
}

/** Where the core density falls to `level` (Å). */
function radiusAt(element: string, level: number): number {
  let r = 0.05;
  while (coreDensity(element, r) > level) r += 0.001;
  return r * ANGSTROM_PER_BOHR;
}

describe('free-atom core densities', () => {
  it('hold their core electrons: Li 2, Na 10, K 18, I 46, Rn 78', () => {
    for (const [element, core] of [['Li', 2], ['Na', 10], ['K', 18], ['I', 46], ['Rn', 78]] as const) {
      expect(electrons(element)).toBeCloseTo(core, 0);
    }
  });

  it("reach 0.001 au where the atoms put it: Na's 10-electron core at 1.32 Å, O's 1s at 0.45 Å", () => {
    expect(radiusAt('Na', 1e-3)).toBeCloseTo(1.32, 1);
    expect(radiusAt('O', 1e-3)).toBeCloseTo(0.45, 1);
  });

  it('are nothing for H and He, which GFN2 treats whole', () => {
    expect(coreDensity('H', 0.5)).toBe(0);
    expect(coreReach('He')).toBe(0);
  });
});
